contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    receive() external payable {}

    function run(uint256 amount1, uint256 amount2) public payable {
        require(amount1 == 10 ether, "first call must send exactly 10 ether");
        require(amount2 == 10 ether, "second call must send exactly 10 ether");
        require(address(this).balance >= amount1 + amount2, "not enough balance for both calls");

        uint256 balanceBefore = address(c).balance;

        bool reverted1;
        try c.fallback{value: amount1}() {
            reverted1 = false;
        } catch {
            reverted1 = true;
        }

        uint256 balanceAfter1 = address(c).balance;

        bool reverted2;
        try c.fallback{value: amount2}() {
            reverted2 = false;
        } catch {
            reverted2 = true;
        }

        uint256 balanceAfter2 = address(c).balance;

        if (!reverted1) {
            if (block.number % 15 == 0) {
                assert(balanceAfter1 == 0);
            } else {
                assert(balanceAfter1 == balanceBefore + amount1);
            }
        }

        if (!reverted2) {
            if (block.number % 15 == 0) {
                assert(balanceAfter2 == 0);
            } else {
                assert(balanceAfter2 == balanceAfter1 + amount2);
            }
        }

        uint256 diff = balanceAfter2 - balanceBefore;
        if (reverted1 && reverted2) {
            assert(diff == 0);
        } else if (!reverted1 && reverted2) {
            assert(balanceAfter2 == balanceAfter1);
        } else if (!reverted1 && !reverted2) {
            assert(diff == amount1 + amount2 || (block.number % 15 == 0 && balanceAfter2 == 0));
        }
    }
}

