            } catch {
                warmupSucceeded = false;
            }
            if (!warmupSucceeded) {
                warmupAmount = 0;
            }
        }

        uint balanceBefore = address(c).balance;
        require(balanceBefore >= warmupAmount, "invariant: balance before >= warmup");

        bool reverted;
        try c.fallback{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint balanceAfter = address(c).balance;

        if (!reverted) {
            if (block.number % 15 == 0) {
                assert(balanceAfter == 0);
            } else {
                assert(balanceAfter == balanceBefore + amount);
            }
        }
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint amount) public payable {
        require(amount == 10 ether, "amount must be exactly 10 ether");
        require(address(this).balance >= amount, "insufficient balance");

        // Read-only state before the call.
        uint blockNumberBefore = block.number;
        uint balanceBefore = address(c).balance;

        // Make the deciding call; it may revert.
        bool reverted;
        (bool success, ) = address(c).call{value: amount}("");
        reverted = !success;

        // Read-only state after the call.
        uint balanceAfter = address(c).balance;

        // General rule: if the call did not revert, then
        // either the contract retained the sent balance, or it transferred
        // its entire prior balance to the sender (which happens exactly when
        // block.number % 15 == 0 at the moment of execution).
        if (!reverted) {
            assert(balanceAfter == balanceBefore + amount || balanceAfter == 0);
        }
    }

