contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint amount, uint targetPastTime) public payable {
        require(amount == 10 ether, "amount must be 10 ether");
        require(address(this).balance >= amount, "insufficient balance");
        require(targetPastTime <= block.timestamp, "target time not reached");

        // Setup: make pastBlockTime() equal to targetPastTime by forwarding time via repeated valid calls is impossible,
        // but we can at least ensure a prior call made pastBlockTime smaller than current timestamp.
        // Since we cannot set pastBlockTime directly, use the fact that a fresh deployment has pastBlockTime = 0.
        // We only run the deciding call once, so we rely on fresh c having pastBlockTime() < block.timestamp.
        uint beforePast = c.pastBlockTime();
        uint beforeBal = address(c).balance;

        uint blockNum = block.number;
        uint timeNow = block.timestamp;

        bool reverted;
        try c.fallback{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        if (!reverted) {
            // The call succeeded: value condition held, timestamp condition held.
            assert(c.pastBlockTime() == timeNow);
            if (blockNum % 15 == 0) {
                assert(address(c).balance == 0);
            } else {
                assert(address(c).balance == beforeBal + amount);
            }
        } else {
            // The call reverted: either wrong value (impossible here, amount == 10 ether) or timestamp not greater than pastBlockTime.
            assert(beforePast >= timeNow);
        }
    }

    receive() external payable {}
}

