        // state a general rule comparing it to the recorded value.
        uint256 timestampBeforeSecond = block.timestamp;
        (bool ok2, ) = address(c).call{value: secondValue}("");

        uint256 afterSecond = c.pastBlockTime();

        // If the first call succeeded, afterFirst is the timestamp of the first call
        // and must be strictly less than or equal to the current timestamp at the start
        // of the second call. A second successful call can only happen if the current
        // timestamp is strictly greater than the previously recorded timestamp, and it
        // must update the recorded timestamp to the current timestamp. If the timestamp
        // is not greater, the call must revert and leave the recorded timestamp unchanged.
        if (ok1) {
            assert(
                (ok2 && secondValue == 10 ether && timestampBeforeSecond > afterFirst && afterSecond == timestampBeforeSecond) ||
                (!ok2 && (secondValue != 10 ether || timestampBeforeSecond <= afterFirst) && afterSecond == afterFirst)
            );
        } else {
            // If the first call reverted, it must be because the value was not
            // exactly 10 ether (or, theoretically, the initial timestamp condition
            // failed, but pastBlockTime starts at 0 so that cannot happen). The
            // state must be unchanged.
            assert(!ok2 ? afterSecond == 0 : true);
        }
    }

    receive() external payable {}
}

