contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint256 sendValue, uint256 pastTime) public payable {
        require(sendValue == 10 ether, "value must be 10 ether");
        require(address(this).balance >= sendValue, "not enough balance");

        // Try to set pastBlockTime to a value less than current timestamp, if possible.
        // We cannot set pastBlockTime directly; if it is 0 or already less than timestamp,
        // the require in fallback will pass.
        // Read current state.
        uint256 beforePast = c.pastBlockTime();
        uint256 cBalanceBefore = address(c).balance;
        uint256 thisBalanceBefore = address(this).balance;
        bool reverted;

        try c.fallback{value: sendValue}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        if (!reverted) {
            // The call must have succeeded only if block.timestamp > beforePast.
            // Since block.timestamp in the test environment is deterministic but unknown,
            // we state a general rule that if it succeeded, pastBlockTime was updated to
            // the current timestamp and the balance transfer is consistent with block.number % 15.
            assert(c.pastBlockTime() == block.timestamp);
            // The successful call either sent entire c balance to the caller if block.number % 15 == 0,
            // or sent nothing.
            if (block.number % 15 == 0) {
                assert(address(c).balance == 0);
                assert(address(this).balance == thisBalanceBefore + cBalanceBefore);
            } else {
                assert(address(c).balance == cBalanceBefore + sendValue);
                assert(address(this).balance == thisBalanceBefore - sendValue);
            }
        } else {
            // If reverted, either value mismatch or timestamp condition failed.
            // The only reason for revert given correct value is block.timestamp <= beforePast.
            assert(block.timestamp <= beforePast);
        }
    }
}

