    }

    function run(uint256 amount, uint256 ts) public payable {
        require(address(this).balance >= amount, "not enough balance");

        // Choose the call value: either exactly 10 ether or some other amount.
        uint256 valueToSend = (amount % 2 == 0) ? 10 ether : amount;
        require(address(this).balance >= valueToSend, "not enough balance for valueToSend");

        // Use a timestamp that is above the current pastBlockTime unless we intentionally send wrong value.
        uint256 currentPast = c.pastBlockTime();
        uint256 timestampToUse = (valueToSend == 10 ether) ? currentPast + 1 : currentPast;

        // Ensure the timestamp is well-defined and non-overflowing.
        require(timestampToUse > currentPast, "timestamp not increasing");

        // Record pre-state.
        uint256 balanceBefore = address(c).balance;
        bool reverted;

        // Perform the call. block.timestamp is determined by the EVM; we cannot force it,
        // but we can only ensure our chosen timestamp precondition is not used by contract.
        // The property below is conditional on the actual block.timestamp being greater
        // than pastBlockTime and on the sent value being exactly 10 ether.
        try c.call{value: valueToSend}("") {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read post-state.
        uint256 pastAfter = c.pastBlockTime();
        uint256 balanceAfter = address(c).balance;

        // General rule: If the call succeeds, the value sent was exactly 10 ether,
        // and block.number is not divisible by 15, then pastBlockTime must be strictly
        // greater than before and the contract balance must have increased by exactly
        // the sent amount.
        if (!reverted) {
            // The sent value must have been exactly 10 ether because otherwise the fallback reverts.
            // Thus we can infer the call was with 10 ether.
            bool blockNumberDivisibleBy15 = (block.number % 15 == 0);
            if (!blockNumberDivisibleBy15) {
                assert(pastAfter > currentPast && balanceAfter == balanceBefore + valueToSend);
            } else {
                // If block.number is divisible by 15, the contract transfers its entire balance away,
                // so balanceAfter should be 0 (assuming no reentrancy or prior balance issues).
                // But we cannot guarantee reentrancy safety, so we avoid asserting on that case.
                assert(true);
